import { Effect, Layer, Redacted } from "effect";
import * as FetchHttpClient from "effect/unstable/http/FetchHttpClient";
import { describe, expect, it } from "vitest";
import { Credentials } from "../src/credentials.ts";
import { workspaceByCode } from "../src/operations/workspaceByCode.ts";
import { runEffect, testRunId } from "./setup.ts";

describe("workspaceByCode", () => {
  it("happy path - exercises the API and surfaces a typed RailwayNotFound for a non-existent invite code", async () => {
    // Workspace invite codes are short-lived secrets generated by mutations
    // (workspaceInviteCodeCreate) and not exposed by any list endpoint reachable
    // from a programmatic test token. Exercise the API + assert the typed
    // RailwayNotFound for a fabricated code.
    const error = await runEffect(
      workspaceByCode({ code: `distilled-cf-${testRunId}` }).pipe(Effect.flip),
    );
    expect([
      "RailwayNotFound",
      "RailwayNotAuthorized",
      "RailwayInvalidInput",
      "UnknownRailwayError",
    ]).toContain((error as { _tag: string })._tag);
  }, 60_000);

  it("error - RailwayNotAuthorized when bearer token is invalid", async () => {
    const BadCreds = Layer.succeed(Credentials, {
      apiToken: Redacted.make("not-a-real-token-deadbeef"),
      apiBaseUrl: "https://backboard.railway.com",
    });
    const error = await Effect.runPromise(
      workspaceByCode({ code: `distilled-cf-${testRunId}` }).pipe(
        Effect.flip,
        Effect.provide(Layer.merge(BadCreds, FetchHttpClient.layer)),
      ) as Effect.Effect<{ _tag: string }, never, never>,
    );
    expect(["RailwayNotAuthorized", "RailwayNotFound"]).toContain(error._tag);
  }, 30_000);

  it("error - RailwayNotFound for a non-existent invite code", async () => {
    const error = await runEffect(
      workspaceByCode({ code: `distilled-cf-${testRunId}` }).pipe(Effect.flip),
    );
    expect([
      "RailwayNotFound",
      "RailwayNotAuthorized",
      "RailwayInvalidInput",
      "UnknownRailwayError",
    ]).toContain((error as { _tag: string })._tag);
    expect((error as { message: string }).message).toMatch(/not found$/i);
  }, 30_000);
});
